const HOUR_MS = 60 * 60 * 1000;
const DAY_MS = 24 * HOUR_MS;

const STATUSES = new Set(["pending", "request_sent", "confirmed", "reminder_sent", "completed"]);
const PHASES = new Set([
  "idle", "request_prepared", "request_ambiguous",
  "reminder_prepared", "reminder_ambiguous",
  "thanks_prepared", "thanks_ambiguous", "needs_reconciliation"
]);
const EVENT_STATUSES = new Set(["pending", "processed", "ambiguous", "invalid"]);

const parseDate = value => {
  if (typeof value !== "string") return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) || !/[zZ]|[+-]\d\d:\d\d$/.test(value) ? null : date;
};

const validPhone = value =>
  typeof value === "string" && /^\+[1-9]\d{7,14}$/.test(value);

const validBoolean = value => typeof value === "boolean";

const validHttpsUrl = value => {
  if (typeof value !== "string" || /\s/.test(value)) return false;
  if (typeof URL === "function") {
    try {
      const parsed = new URL(value);
      return parsed.protocol === "https:" && Boolean(parsed.hostname);
    } catch {
      return false;
    }
  }
  const match = value.match(/^https:\/\/([^/?#]+)(?:[/?#][^\s]*)?$/i);
  if (!match || match[1].includes("@")) return false;

  let host = match[1];
  let port = null;

  if (host.startsWith("[")) {
    const closing = host.indexOf("]");
    if (closing < 2 || !/^[0-9a-f:.]+$/i.test(host.slice(1, closing))) return false;
    const remainder = host.slice(closing + 1);
    if (remainder && !/^:\d+$/.test(remainder)) return false;
    port = remainder ? remainder.slice(1) : null;
  } else {
    if ((host.match(/:/g) ?? []).length > 1) return false;
    const colon = host.lastIndexOf(":");
    if (colon >= 0) {
      port = host.slice(colon + 1);
      host = host.slice(0, colon);
    }
    const labels = host.split(".");
    if (
      !labels.length ||
      labels.some(label =>
        !/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(label)
      )
    ) return false;
  }

  return port === null ||
    (/^\d{1,5}$/.test(port) && Number(port) >= 1 && Number(port) <= 65535);
};

function validateService(service) {
  const errors = [];

  if (
    !service ||
    typeof service.service_id !== "string" ||
    !service.service_id.trim()
  ) errors.push("INVALID_SERVICE_ID");

  if (!validPhone(service?.phone_e164)) errors.push("INVALID_PHONE");
  if (!parseDate(service?.appointment_at)) errors.push("INVALID_APPOINTMENT_AT");
  if (!STATUSES.has(service?.status)) errors.push("INVALID_STATUS");
  if (!PHASES.has(service?.operation_phase)) errors.push("INVALID_OPERATION_PHASE");

  for (const key of [
    "request_sent", "review_confirmed", "reminder_sent", "thanks_sent"
  ]) {
    if (!validBoolean(service?.[key])) {
      errors.push(`INVALID_${key.toUpperCase()}`);
    }
    if (service?.[key] === true && !parseDate(service?.[`${key}_at`])) {
      errors.push(`MISSING_${key.toUpperCase()}_AT`);
    }
  }

  for (const key of [
    "request_sent_at", "review_confirmed_at",
    "reminder_sent_at", "thanks_sent_at", "completed_at"
  ]) {
    if (service?.[key] && !parseDate(service[key])) {
      errors.push(`INVALID_${key.toUpperCase()}`);
    }
  }

  if (
    service?.completed_at &&
    !["reminder_finished", "confirmed_thanked"].includes(service?.completion_reason)
  ) errors.push("INVALID_COMPLETION_REASON");

  if (service?.completion_reason && !service?.completed_at) {
    errors.push("MISSING_COMPLETED_AT");
  }

  if (
    service?.completion_reason === "confirmed_thanked" &&
    service?.thanks_sent !== true
  ) errors.push("CONFIRMED_THANKED_WITHOUT_THANKS");

  if (
    service?.request_sent === false &&
    ["request_sent", "confirmed", "reminder_sent", "completed"].includes(service?.status)
  ) errors.push("STATUS_REQUIRES_REQUEST_SENT");

  if (service?.review_confirmed === true && service?.request_sent !== true) {
    errors.push("CONFIRMATION_REQUIRES_REQUEST");
  }
  if (service?.reminder_sent === true && service?.request_sent !== true) {
    errors.push("REMINDER_REQUIRES_REQUEST");
  }
  if (service?.thanks_sent === true && service?.review_confirmed !== true) {
    errors.push("THANKS_REQUIRES_CONFIRMATION");
  }
  if (service?.status === "confirmed" && service?.review_confirmed !== true) {
    errors.push("STATUS_REQUIRES_CONFIRMATION");
  }
  if (service?.status === "completed" && !service?.completion_reason) {
    errors.push("COMPLETED_REQUIRES_REASON");
  }
  if (service?.review_confirmed === true && service?.status === "pending") {
    errors.push("CONFIRMED_PENDING_CONTRADICTION");
  }
  if (!validHttpsUrl(service?.review_link)) {
    errors.push("INVALID_REVIEW_LINK");
  }

  return [...new Set(errors)];
}

function validateEvent(event) {
  const errors = [];
  if (
    !event ||
    typeof event.provider_event_id !== "string" ||
    !event.provider_event_id.trim()
  ) errors.push("INVALID_WEBHOOK_EVENT");
  if (!validPhone(event?.phone_e164)) errors.push("INVALID_PHONE");
  if (!parseDate(event?.received_at)) errors.push("INVALID_DATE");
  if (event?.event_type !== "LISTO") errors.push("INVALID_WEBHOOK_EVENT");
  if (!EVENT_STATUSES.has(event?.processing_status)) {
    errors.push("INVALID_EVENT_STATUS");
  }
  return [...new Set(errors)];
}

function eligibleForRequest(service, now, config) {
  const at = parseDate(service.appointment_at);
  return service.status === "pending" &&
    !service.request_sent &&
    service.operation_phase === "idle" &&
    now.getTime() >= at.getTime() + config.requestDelayHours * HOUR_MS;
}

function eligibleForReminder(service, now, config) {
  const sent = parseDate(service.request_sent_at);
  return service.request_sent &&
    !service.review_confirmed &&
    !service.reminder_sent &&
    service.operation_phase === "idle" &&
    sent &&
    now.getTime() >= sent.getTime() + config.reminderDelayHours * HOUR_MS;
}

function correlationForEvent(event, services, config) {
  const received = parseDate(event.received_at);

  if (!received) {
    return {
      candidates: [],
      potential: services.filter(s => s?.phone_e164 === event.phone_e164),
      uncertain: true
    };
  }

  const candidates = [];
  const potential = [];
  let uncertain = false;

  for (const service of services) {
    if (service?.phone_e164 !== event.phone_e164) continue;

    if (service.request_sent !== true) {
      if (service.request_sent !== false) {
        uncertain = true;
        potential.push(service);
      }
      continue;
    }

    const sent = parseDate(service.request_sent_at);

    if (!sent) {
      uncertain = true;
      potential.push(service);
      continue;
    }

    if (
      received.getTime() >= sent.getTime() &&
      received.getTime() <=
        sent.getTime() + config.confirmationWindowDays * DAY_MS
    ) {
      candidates.push(service);
      potential.push(service);
    }
  }

  return { candidates, potential, uncertain };
}

// CONFIGURACIÓN LOCAL — CA09
// Todas las compuertas de producción permanecen cerradas.
const localConfig = {
  confirmationWindowDays: 7,
  timezone: "",
  allowedStart: "",
  allowedEnd: "",
  criticalConfigPresent: false,
  exclusiveExecutionVerified: false,
  sheetsWriteEnabled: false,
  sendEnabled: false,
  authorizedServiceIds: [],
  ca09Test: {
    enabled: true,
    serviceId: "synthetic-ca09-service-1",
    operationKind: "request"
  },
  coordinator: {
    apiVersion: "v1",
    baseUrl: "http://host.docker.internal:18787",
    requestTimeoutMs: 20000,
    testMode: true,
    providerMode: "simulated"
  }
};

// ENTRADAS
const envelopes = $input.all().map(i => i.json);
const servicesEnvelope = envelopes.find(x => x.source === "services");
const eventsEnvelope = envelopes.find(x => x.source === "inbox_events");

if (!servicesEnvelope || !eventsEnvelope) {
  throw new Error("RF01_READ_INCOMPLETE");
}

const ran = name => {
  try {
    return Boolean($(name).first());
  } catch {
    return false;
  }
};

const manualRun = ran("Manual Trigger");
const scheduledRun = ran("Schedule Trigger (requires RF01_SCHEDULE_CRON)");

const executionMode =
  manualRun && !scheduledRun ? "manual_test" :
  scheduledRun && !manualRun ? "scheduled_operational" :
  "unknown_blocked";

const bool = v =>
  v === true || String(v ?? "").trim().toLowerCase() === "true";

const nullable = v =>
  v === "" || v === undefined || v === null ? null : v;

const flag = v => {
  if (v === true || v === false) return v;
  if (
    typeof v === "string" &&
    /^(true|false)$/i.test(v.trim())
  ) return v.trim().toLowerCase() === "true";
  return v;
};

const services = servicesEnvelope.rows.map(r => {
  const s = { ...r };
  for (const k of [
    "request_sent", "review_confirmed", "reminder_sent", "thanks_sent"
  ]) s[k] = flag(s[k]);

  for (const k of [
    "request_sent_at", "review_confirmed_at", "reminder_sent_at",
    "thanks_sent_at", "completed_at", "completion_reason", "error_code"
  ]) s[k] = nullable(s[k]);

  return s;
});

const events = eventsEnvelope.rows.map(r => ({
  ...r,
  service_id: nullable(r.service_id)
}));

const now = new Date();

const config = {
  requestDelayHours: 2,
  reminderDelayHours: 12,
  confirmationWindowDays: Number(localConfig.confirmationWindowDays),
  timezone: String(localConfig.timezone || ""),
  allowedStart: String(localConfig.allowedStart || ""),
  allowedEnd: String(localConfig.allowedEnd || ""),
  criticalConfigPresent:
    executionMode === "scheduled_operational" &&
    bool(localConfig.criticalConfigPresent),
  contactAuthorized: false,
  exclusiveExecutionVerified:
    executionMode === "scheduled_operational" &&
    bool(localConfig.exclusiveExecutionVerified),
  sheetsWriteEnabled:
    executionMode === "scheduled_operational" &&
    bool(localConfig.sheetsWriteEnabled),
  sendEnabled:
    executionMode === "scheduled_operational" &&
    bool(localConfig.sendEnabled),
  authorizedServiceIds: new Set(
    Array.isArray(localConfig.authorizedServiceIds)
      ? localConfig.authorizedServiceIds
          .map(x => String(x).trim())
          .filter(Boolean)
      : []
  ),
  coordinator: { ...localConfig.coordinator }
};

// VALIDACIONES
const validation = [];
const serviceCounts = new Map();
const eventCounts = new Map();
const configurationErrors = [];

if (
  !Number.isFinite(config.confirmationWindowDays) ||
  config.confirmationWindowDays <= 0
) configurationErrors.push("INVALID_CONFIRMATION_WINDOW");

if (
  config.sendEnabled &&
  (
    !config.timezone ||
    !/^\d\d:\d\d$/.test(config.allowedStart) ||
    !/^\d\d:\d\d$/.test(config.allowedEnd)
  )
) configurationErrors.push("INVALID_ALLOWED_SCHEDULE");

for (const s of services) {
  const errors = validateService(s);
  serviceCounts.set(s.service_id, (serviceCounts.get(s.service_id) || 0) + 1);
  if (errors.length) {
    validation.push({ record: "service", id: s.service_id, errors });
  }
}

for (const [id, count] of serviceCounts) {
  if (count > 1) {
    validation.push({
      record: "service",
      id,
      errors: ["DUPLICATE_SERVICE_ID"]
    });
  }
}

for (const e of events) {
  const errors = validateEvent(e);
  eventCounts.set(
    e.provider_event_id,
    (eventCounts.get(e.provider_event_id) || 0) + 1
  );
  if (errors.length) {
    validation.push({ record: "event", id: e.provider_event_id, errors });
  }
}

for (const [id, count] of eventCounts) {
  if (count > 1) {
    validation.push({
      record: "event",
      id,
      errors: ["DUPLICATE_PROVIDER_EVENT_ID"]
    });
  }
}

const invalidServices = new Set(
  validation.filter(x => x.record === "service").map(x => x.id)
);
const invalidEvents = new Set(
  validation.filter(x => x.record === "event").map(x => x.id)
);

let command = null;
const eventDiagnostics = [];
const unresolvedServices = new Set();

// EVENTOS
for (const e of events) {
  if (!["pending", "ambiguous"].includes(e.processing_status)) continue;

  if (invalidEvents.has(e.provider_event_id)) {
    for (const s of services) {
      if (s.phone_e164 === e.phone_e164) {
        unresolvedServices.add(s.service_id);
      }
    }
    eventDiagnostics.push({
      id: e.provider_event_id,
      result: "BLOCKED_INVALID_OR_DUPLICATE_EVENT"
    });
    continue;
  }

  const correlation = correlationForEvent(
    e,
    services,
    { confirmationWindowDays: config.confirmationWindowDays }
  );

  if (
    correlation.uncertain ||
    correlation.candidates.length !== 1 ||
    invalidServices.has(correlation.candidates[0]?.service_id)
  ) {
    for (const s of correlation.potential) {
      unresolvedServices.add(s.service_id);
    }
    eventDiagnostics.push({
      id: e.provider_event_id,
      result: "NEEDS_RECONCILIATION"
    });
    continue;
  }

  if (command) continue;

  const s = correlation.candidates[0];

  if (!s.review_confirmed) {
    command = {
      kind: "confirm",
      service_id: s.service_id,
      provider_event_id: e.provider_event_id,
      received_at: e.received_at,
      service: s,
      event: e
    };
  } else {
    command = {
      kind: "mark_duplicate_event",
      service_id: s.service_id,
      provider_event_id: e.provider_event_id,
      service: s,
      event: e
    };
  }
}

// POLÍTICA HORARIA
function scheduleAllowed() {
  if (
    !config.timezone ||
    !/^\d\d:\d\d$/.test(config.allowedStart) ||
    !/^\d\d:\d\d$/.test(config.allowedEnd)
  ) return false;

  try {
    const parts = new Intl.DateTimeFormat("en-GB", {
      timeZone: config.timezone,
      hour: "2-digit",
      minute: "2-digit",
      hourCycle: "h23"
    }).formatToParts(now);

    const hm =
      parts.find(x => x.type === "hour").value + ":" +
      parts.find(x => x.type === "minute").value;

    return config.allowedStart <= config.allowedEnd
      ? hm >= config.allowedStart && hm <= config.allowedEnd
      : hm >= config.allowedStart || hm <= config.allowedEnd;
  } catch {
    return false;
  }
}

// SELECCIÓN DE COMANDO
// Corrección CA09: aislar el servicio sintético durante la prueba manual.
const ca09ManualOnly =
  executionMode === "manual_test" &&
  localConfig.ca09Test?.enabled === true;

if (!command) {
  const eligiblePool = [...services]
    .filter(s =>
      !ca09ManualOnly ||
      s.service_id === localConfig.ca09Test.serviceId
    )
    .sort((a, b) =>
      String(a.service_id).localeCompare(String(b.service_id))
    );

  for (const s of eligiblePool) {
    if (
      invalidServices.has(s.service_id) ||
      unresolvedServices.has(s.service_id) ||
      s.operation_phase !== "idle"
    ) continue;

    let kind = null;

    if (s.review_confirmed && !s.thanks_sent) {
      kind = "thanks";
    } else if (eligibleForRequest(s, now, { requestDelayHours: 2 })) {
      kind = "request";
    } else if (eligibleForReminder(s, now, { reminderDelayHours: 12 })) {
      kind = "reminder";
    }

    if (kind) {
      command = {
        kind,
        service_id: s.service_id,
        service: s
      };
      break;
    }
  }
}

// SEGURIDAD Y AUTORIZACIÓN
const writeAuthorized =
  config.exclusiveExecutionVerified && config.sheetsWriteEnabled;

const isOutgoingCommand =
  command && ["request", "reminder", "thanks"].includes(command.kind);

const coordinatorUrl =
  String(config.coordinator.baseUrl || "").replace(/\/$/, "");

const coordinatorTimeoutMs =
  Number(config.coordinator.requestTimeoutMs);

function coordinatorUrlAllowed(value) {
  if (
    typeof value !== "string" ||
    /\s|\\/.test(value)
  ) return false;

  const match = /^(https?):\/\/([^/?#]+)(?:[/?#].*)?$/i.exec(value);
  if (!match || match[2].includes("@")) return false;

  const authority = match[2];
  let hostname = "";
  let port = "";

  if (authority.startsWith("[")) {
    const end = authority.indexOf("]");
    if (end < 0) return false;
    hostname = authority.slice(0, end + 1).toLowerCase();
    const rest = authority.slice(end + 1);
    if (rest && !rest.startsWith(":")) return false;
    port = rest.slice(1);
  } else {
    const parts = authority.split(":");
    if (parts.length > 2) return false;
    hostname = parts[0].toLowerCase();
    port = parts[1] || "";
  }

  if (
    !hostname ||
    (
      port &&
      (!/^\d+$/.test(port) || Number(port) < 1 || Number(port) > 65535)
    )
  ) return false;

  const protocol = match[1].toLowerCase() + ":";
  if (protocol === "https:") return true;

  const localGatesClosed = ![
    localConfig.criticalConfigPresent,
    localConfig.exclusiveExecutionVerified,
    localConfig.sheetsWriteEnabled,
    localConfig.sendEnabled
  ].some(bool);

  return (
    protocol === "http:" &&
    hostname === "host.docker.internal" &&
    executionMode === "manual_test" &&
    config.coordinator.testMode === true &&
    config.coordinator.providerMode === "simulated" &&
    localGatesClosed
  );
}

const coordinatorConfigured =
  config.coordinator.apiVersion === "v1" &&
  coordinatorUrlAllowed(coordinatorUrl) &&
  Number.isSafeInteger(coordinatorTimeoutMs) &&
  coordinatorTimeoutMs >= 1000 &&
  coordinatorTimeoutMs <= 120000;

const sendAuthorized =
  writeAuthorized &&
  config.sendEnabled &&
  config.criticalConfigPresent &&
  config.authorizedServiceIds.has(command?.service_id) &&
  scheduleAllowed() &&
  coordinatorConfigured;

const ca09 = localConfig.ca09Test || {};

const ca09TestAuthorized = Boolean(
  command &&
  executionMode === "manual_test" &&
  coordinatorConfigured &&
  ca09.enabled === true &&
  /^synthetic-ca09-[A-Za-z0-9._:-]+$/.test(ca09.serviceId) &&
  command.service_id === ca09.serviceId &&
  command.kind === ca09.operationKind &&
  command.kind === "request" &&
  !writeAuthorized &&
  !config.sendEnabled &&
  !config.criticalConfigPresent
);

const executionAuthorized = Boolean(
  command &&
  configurationErrors.length === 0 &&
  (
    (isOutgoingCommand ? sendAuthorized : writeAuthorized) ||
    ca09TestAuthorized
  )
);

return [{
  json: {
    workflow: "RF-01",
    mode: "SAFE_DISABLED_BY_DEFAULT",
    execution_mode: executionMode,
    execution_id: String($execution.id || ""),
    checked_at: now.toISOString(),
    services_read: services.length,
    events_read: events.length,
    validation,
    configuration_errors: configurationErrors,
    event_diagnostics: eventDiagnostics,
    command,
    execution_authorized: executionAuthorized,
    ca09_test_authorized: ca09TestAuthorized,
    gates: {
      exclusive_execution: config.exclusiveExecutionVerified,
      sheets_write: config.sheetsWriteEnabled,
      send: config.sendEnabled,
      critical_config: config.criticalConfigPresent,
      contact_authorized:
        config.authorizedServiceIds.has(command?.service_id),
      schedule_allowed: scheduleAllowed()
    },
    policy: {
      confirmationWindowDays: config.confirmationWindowDays
    },
    coordinator: {
      apiVersion: config.coordinator.apiVersion,
      baseUrl: coordinatorUrl,
      requestTimeoutMs: coordinatorTimeoutMs,
      urlAllowed: coordinatorConfigured
    }
  }
}];

const STATUSES = new Set(["pending", "request_sent", "confirmed", "reminder_sent", "completed"]);
const PHASES = new Set([
  "idle", "request_prepared", "request_ambiguous", "reminder_prepared",
  "reminder_ambiguous", "thanks_prepared", "thanks_ambiguous", "needs_reconciliation"
]);
const EVENT_STATUSES = new Set(["pending", "processed", "ambiguous", "invalid"]);

const parseDate = value => {
  if (typeof value !== "string") return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) || !/[zZ]|[+-]\d\d:\d\d$/.test(value) ? null : date;
};

const validPhone = value => typeof value === "string" && /^\+[1-9]\d{7,14}$/.test(value);

const validHttpsUrl = value => {
  if (typeof value !== "string" || /\s/.test(value)) return false;
  const match = value.match(/^https:\/\/([^/?#]+)(?:[/?#][^\s]*)?$/i);
  if (!match || match[1].includes("@")) return false;

  let host = match[1], port = null;

  if (host.startsWith("[")) {
    const closing = host.indexOf("]");
    if (closing < 2 || !/^[0-9a-f:.]+$/i.test(host.slice(1, closing))) return false;
    const remainder = host.slice(closing + 1);
    if (remainder && !/^:\d+$/.test(remainder)) return false;
    port = remainder ? remainder.slice(1) : null;
  } else {
    if ((host.match(/:/g) ?? []).length > 1) return false;
    const colon = host.lastIndexOf(":");
    if (colon >= 0) {
      port = host.slice(colon + 1);
      host = host.slice(0, colon);
    }
    const labels = host.split(".");
    if (!labels.length || labels.some(label =>
      !/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(label)
    )) return false;
  }

  return port === null || (
    /^\d{1,5}$/.test(port) && Number(port) >= 1 && Number(port) <= 65535
  );
};

function validateService(s) {
  const errors = [];

  if (!s || typeof s.service_id !== "string" || !s.service_id.trim())
    errors.push("INVALID_SERVICE_ID");
  if (!validPhone(s?.phone_e164)) errors.push("INVALID_PHONE");
  if (!parseDate(s?.appointment_at)) errors.push("INVALID_APPOINTMENT_AT");
  if (!STATUSES.has(s?.status)) errors.push("INVALID_STATUS");
  if (!PHASES.has(s?.operation_phase)) errors.push("INVALID_OPERATION_PHASE");

  for (const key of ["request_sent", "review_confirmed", "reminder_sent", "thanks_sent"]) {
    if (typeof s?.[key] !== "boolean")
      errors.push(`INVALID_${key.toUpperCase()}`);
    if (s?.[key] === true && !parseDate(s?.[`${key}_at`]))
      errors.push(`MISSING_${key.toUpperCase()}_AT`);
  }

  for (const key of [
    "request_sent_at", "review_confirmed_at", "reminder_sent_at",
    "thanks_sent_at", "completed_at"
  ]) {
    if (s?.[key] && !parseDate(s[key]))
      errors.push(`INVALID_${key.toUpperCase()}`);
  }

  if (s?.completed_at &&
      !["reminder_finished", "confirmed_thanked"].includes(s?.completion_reason))
    errors.push("INVALID_COMPLETION_REASON");
  if (s?.completion_reason && !s?.completed_at)
    errors.push("MISSING_COMPLETED_AT");
  if (s?.completion_reason === "confirmed_thanked" && s?.thanks_sent !== true)
    errors.push("CONFIRMED_THANKED_WITHOUT_THANKS");

  if (s?.request_sent === false &&
      ["request_sent", "confirmed", "reminder_sent", "completed"].includes(s?.status))
    errors.push("STATUS_REQUIRES_REQUEST_SENT");
  if (s?.review_confirmed === true && s?.request_sent !== true)
    errors.push("CONFIRMATION_REQUIRES_REQUEST");
  if (s?.reminder_sent === true && s?.request_sent !== true)
    errors.push("REMINDER_REQUIRES_REQUEST");
  if (s?.thanks_sent === true && s?.review_confirmed !== true)
    errors.push("THANKS_REQUIRES_CONFIRMATION");
  if (s?.status === "confirmed" && s?.review_confirmed !== true)
    errors.push("STATUS_REQUIRES_CONFIRMATION");
  if (s?.status === "completed" && !s?.completion_reason)
    errors.push("COMPLETED_REQUIRES_REASON");
  if (s?.review_confirmed === true && s?.status === "pending")
    errors.push("CONFIRMED_PENDING_CONTRADICTION");
  if (!validHttpsUrl(s?.review_link))
    errors.push("INVALID_REVIEW_LINK");

  return [...new Set(errors)];
}

function validateEvent(e) {
  const errors = [];
  if (!e || typeof e.provider_event_id !== "string" || !e.provider_event_id.trim())
    errors.push("INVALID_WEBHOOK_EVENT");
  if (!validPhone(e?.phone_e164)) errors.push("INVALID_PHONE");
  if (!parseDate(e?.received_at)) errors.push("INVALID_DATE");
  if (e?.event_type !== "LISTO") errors.push("INVALID_WEBHOOK_EVENT");
  if (!EVENT_STATUSES.has(e?.processing_status))
    errors.push("INVALID_EVENT_STATUS");
  return [...new Set(errors)];
}

function correlationForEvent(event, services, config) {
  const received = parseDate(event.received_at);
  if (!received)
    return {
      candidates: [],
      potential: services.filter(s => s?.phone_e164 === event.phone_e164),
      uncertain: true
    };

  const candidates = [], potential = [];
  let uncertain = false;

  for (const s of services) {
    if (s?.phone_e164 !== event.phone_e164) continue;

    if (s.request_sent !== true) {
      if (s.request_sent !== false) {
        uncertain = true;
        potential.push(s);
      }
      continue;
    }

    const sent = parseDate(s.request_sent_at);
    if (!sent) {
      uncertain = true;
      potential.push(s);
      continue;
    }

    if (
      received.getTime() >= sent.getTime() &&
      received.getTime() <=
        sent.getTime() + config.confirmationWindowDays * 86400000
    ) {
      candidates.push(s);
      potential.push(s);
    }
  }

  return { candidates, potential, uncertain };
}

const action = $("Filter outgoing command").first().json;
const inputs = $input.all().map(i => i.json);

const se = inputs.find(x => x.source === "services");
const ee = inputs.find(x => x.source === "inbox_events");

if (!se || !ee) throw new Error("OUTGOING_REREAD_INCOMPLETE");

const normalize = s => {
  const x = { ...s };

  for (const key of [
    "request_sent", "review_confirmed", "reminder_sent", "thanks_sent"
  ]) {
    if (
      typeof x[key] === "string" &&
      /^(true|false)$/i.test(x[key].trim())
    ) {
      x[key] = x[key].trim().toLowerCase() === "true";
    }
  }

  for (const key of [
    "request_sent_at", "review_confirmed_at", "reminder_sent_at",
    "thanks_sent_at", "completed_at", "completion_reason", "error_code"
  ]) {
    if (x[key] === "" || x[key] === undefined) x[key] = null;
  }

  return x;
};

const allServices = se.rows.map(normalize);
const rows = allServices.filter(r => r.service_id === action.service_id);

if (
  rows.length !== 1 ||
  rows[0].phone_e164 !== action.service?.phone_e164
) {
  throw new Error("OUTGOING_IDENTITY_MISMATCH");
}

const fresh = rows[0];
if (validateService(fresh).length)
  throw new Error("OUTGOING_SERVICE_INVALID");

if (action.kind === "reminder") {
  const windowDays = Number(action.policy?.confirmationWindowDays);

  if (!Number.isFinite(windowDays) || windowDays <= 0)
    throw new Error("INVALID_CONFIRMATION_WINDOW");

  for (const e of ee.rows.filter(e =>
    ["pending", "ambiguous"].includes(e.processing_status)
  )) {
    if (validateEvent(e).length && e.phone_e164 === fresh.phone_e164)
      throw new Error("REMINDER_BLOCKED_BY_UNCERTAIN_EVENT");

    const c = correlationForEvent(e, allServices, {
      confirmationWindowDays: windowDays
    });

    if (
      (c.uncertain && c.potential.some(s => s.service_id === fresh.service_id)) ||
      c.candidates.some(s => s.service_id === fresh.service_id)
    ) {
      throw new Error("REMINDER_BLOCKED_BY_UNRESOLVED_EVENT");
    }
  }
}

const baseUrl = String(action.coordinator?.baseUrl || "")
  .replace(/\/$/, "");

const ca09Local =
  action.kind === "request" &&
  action.service_id === "synthetic-ca09-service-1" &&
  fresh.phone_e164 === "+12025550109" &&
  baseUrl === "http://host.docker.internal:18787";

const secureEndpoint = /^https:\/\/[^\s/?#@]+/.test(baseUrl);

if (
  !action.executionId ||
  action.coordinator?.apiVersion !== "v1" ||
  (!secureEndpoint && !ca09Local)
) {
  throw new Error("COORDINATOR_CONFIG_INVALID");
}

return [{
  json: {
    ...action,
    service: fresh,
    coordinatorUrl: baseUrl + "/v1/services/state/resolve",
    coordinatorTimeoutMs: action.coordinator.requestTimeoutMs,
    coordinatorRequest: {
      apiVersion: "v1",
      service: fresh
    }
  }
}];
